"""Solution dataclass entities. Can be autogenerated using the server openapi spec."""

from dataclasses import dataclass


@dataclass
class AvailableMeshProperty:
    id: str
    label: str
    tooltip: str


@dataclass
class AvailableResult:
    name: str
    native_location: str
    physical_name: str
    n_components: int
    units: str


@dataclass
class AveragingMeshProperties:
    available: list[AvailableMeshProperty]
    defaults: list[str]


@dataclass
class TimeFrequency:
    value: float
    set_id: int
    step: int | None = None
    substep: int | None = None
